Set env SHOP_RACY=1 to run the ORIGINAL buggy handler (check-then-act race).
Default is the fixed atomic conditional UPDATE version.
"""
import os
import sqlite3

from flask import Flask, g, jsonify

DB_PATH = os.path.join(os.path.dirname(__file__), 'shop.db')
RACY = os.environ.get('SHOP_RACY') == '1'


def get_db():
    conn = getattr(g, '_db', None)
    if conn is None:
        # A fresh connection per request context; SQLite handles the
        # cross-thread serialization via its own locks + busy timeout.
        conn = g._db = sqlite3.connect(DB_PATH, timeout=30)
        conn.row_factory = sqlite3.Row
        conn.execute('PRAGMA journal_mode=WAL')
    return conn


@app_teardown := None  # placeholder removed below


def create_app():
    app = Flask(__name__)

    @app.teardown_appcontext
    def close_db(exc):
        conn = getattr(g, '_db', None)
        if conn is not None:
            conn.close()

    @app.post('/buy/<int:item_id>')
    def buy(item_id):
        db = get_db()
        if RACY:
            # ---- ORIGINAL BUGGY HANDLER (verbatim) ----
            row = db.execute('SELECT stock FROM items WHERE id=?', (item_id,)).fetchone()
            if row['stock'] <= 0:
                return jsonify(error='sold_out'), 409
            db.execute('UPDATE items SET stock=stock-1 WHERE id=?', (item_id,))
            db.commit()
            return jsonify(ok=True)
        else:
            # ---- FIXED: single atomic conditional UPDATE, decide on rowcount ----
            cur = db.execute(
                'UPDATE items SET stock=stock-1 WHERE id=? AND stock>0', (item_id,)
            )
            db.commit()
            if cur.rowcount == 0:
                return jsonify(error='sold_out'), 409
            return jsonify(ok=True)

    return app


def init_db():
    """Fresh DB with one item, stock=5."""
    if os.path.exists(DB_PATH):
        os.remove(DB_PATH)
    for suffix in ('-wal', '-shm'):
        p = DB_PATH + suffix
        if os.path.exists(p):
            os.remove(p)
    conn = sqlite3.connect(DB_PATH)
    conn.execute('CREATE TABLE items (id INTEGER PRIMARY KEY, stock INTEGER NOT NULL)')
    conn.execute('INSERT INTO items (id, stock) VALUES (1, 5)')
    conn.commit()
    conn.close()


app = create_app()

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000, threaded=True)
